 function bankHtml(){if(!g.weekly)return '<p>O banco abre quando o calendário semanal começa.</p>';const L=g.loan;if(L){const left=Math.max(0,L.weeks-L.paidWeeks);return '<div class="loan-active'+(L.late?' late':'')+'"><b>Empréstimo '+esc(L.name)+' · '+money(L.amount)+'</b><span>Parcela semanal <b class="neg">'+money(-L.installment)+'</b> · faltam '+left+' de '+L.weeks+'</span>'+(L.debt?'<span class="neg">Em atraso: '+money(L.debt)+(L.late>=1?' · no próximo atraso o banco vende seu estoque com 50% de desconto':'')+'</span>':'')+'<small>'+(L.graceLeft?'Carência: mais '+L.graceLeft+' semana'+(L.graceLeft>1?'s':'')+' sem parcela. ':'')+(L.juros?L.juros+'% ao mês · '+L.prazo+' meses. ':'')+'A parcela sai do caixa no fim de cada semana.</small></div>';}const usedWeek=g.bank?.week===C.creditWeek(g);return '<p class="bank-intro">Empréstimo do Banco do Bairro para produzir mais.</p>'+button(usedWeek?'Nova negociação na próxima semana':(creditLocked()?'🔒 Libera com '+money(C.Prog.CREDIT_AT)+' faturados':'💼 Negociar empréstimo'),'bankOpen',usedWeek||creditLocked()?'disabled':'','primary')+'<div class="loan-offers" hidden>'+C.loanStatus(g).map(o=>'<div class="loan-offer'+(o.open?'':' locked')+'"><i>'+esc(o.name)+'</i><b class="lo-amt">'+money(o.amount)+'</b><ul><li><span>📅 Prazo</span><b>'+o.weeks+' semanas</b></li><li><span>% Juros</span><b>'+Math.round(o.rate*100)+'%</b></li><li><span>🔁 Parcela</span><b>'+money(o.installment)+'</b></li><li><span>Σ Total</span><b>'+money(o.total)+'</b></li></ul>'+(o.open?button('Pegar empréstimo','loanTake','data-id="'+o.id+'"','primary'):'<small>🔒 Lucre com mais '+o.missing+' produto'+(o.missing>1?'s':'')+'</small>')+'</div>').join('')+'</div><small>Se faltar caixa: multa de 10% e, no segundo atraso, o banco vende seu estoque com 50% de desconto.</small>';}
 function workshopLayout(){const work=!!g.job,operating=['selling','launching'].includes(g.phase);if(workshopPhase!==g.phase){workshopPhase=g.phase;workshopCollapsed=work||operating;}const dock=workshopCollapsed||g.phase==='intro',game=$('game');game.classList.toggle?.('editor-open',!dock);game.classList.toggle?.('workshop-open',dock);$('tray').hidden=dock;$('world').dataset&&( $('world').dataset.mode=dock?'workshop':'creation');$('nav-stock').textContent=(g.stock||0)+(g.portfolio||[]).reduce((n,p)=>n+p.stock,0);const order=$('work-order');order.hidden=!dock;for(const id of ['office','products','clients','ledger'])$(id).classList.toggle?.('active',id===(infoView|| (overviewOpen?'products':'office')));const task=g.crew||g.job,ratio=task?Math.max(0,Math.min(1,task.elapsed/task.duration)):0;const orderKey=turbo+'|'+g.phase+'|'+(task?.type||'')+'|'+g.sold+'|'+g.stock+(g.personaSet==='v2'?'':'|'+g.name);if(orderKey!==orderSignature&&!typingIn('work-order')){orderSignature=orderKey;order.innerHTML='<div class="order-icon">'+gadgetArt()+'</div><div class="order-copy"><small>'+(['personaResearch','gadgetResearch'].includes(g.phase)?'PESQUISA EM ANDAMENTO':operating?'PORTAS ABERTAS':work?'NO COMPUTADOR':'SEU QUARTO')+'</small>'+(g.personaSet==='v2'&&g.productId&&(g.name||'').trim()?'<input class="order-name" id="order-name" maxlength="28" aria-label="Nome do produto" title="Clique para renomear" value="'+esc(g.name)+'">':'<b>'+esc(g.productId?g.name:'Um computador. Sua próxima ideia.')+'</b>')+(task?'<div class="progress"><i id="order-progress" style="width:'+ratio*100+'%"></i></div><span id="order-percent">'+Math.floor(ratio*100)+'% · '+(g.crew?'Montando o lote':'Trabalho em andamento')+'</span>':operating?'<span>'+g.sold+' vendas · '+g.stock+' em estoque</span>':'')+button(g.phase==='intro'?'COMEÇAR':g.phase==='design'?'EDITAR PRODUTO':['personaResearch','gadgetResearch'].includes(g.phase)?'VER PESQUISA':operating||work?'ACOMPANHAR':'CONTINUAR →',g.phase==='intro'?'start':'workbench')+'</div>';const sprite=order.querySelector?.('.product-sprite');if(sprite){const c=sprite.getContext('2d');c.setTransform(4,0,0,4,0,0);c.clearRect(0,0,32,28);PilotWorld.headphones(c,16,15,g.productId||'headphones','#c89659',1.3);}}paintProducts();}
 function creationPanel(){chooseGuide('CRIAR PRODUTO',g.name,'');return '<header class="creation-title"><small>NA PRANCHETA</small><h2>CRIAR PRODUTO</h2></header><div class="creation-route"><span class="active">PRODUTO</span><i>›</i><span>PROTÓTIPO</span><i>›</i><span>MARKETING</span><i>›</i><span>LOTE E PREÇO</span><i>›</i><span>LANÇAMENTO</span></div>'+(g.boardCampaign&&gridPanel(g.attributes).startsWith('<div class="pw ')?'':'<div class="creation-hero">'+gadgetArt()+'<div>'+((g.name||'').trim()?'<h2 class="product-title">'+esc(g.name)+'</h2>':'')+(C.client(g)?'<small class="hero-for">Para '+esc(C.client(g).name)+'</small>':'')+'</div></div>')+(g.boardCampaign?gridPanel(g.attributes):'<div class="points-heading"><b>PONTOS: '+C.G.total(g)+' / '+C.pointBudget(g)+'</b><small>máximo 5 por atributo</small></div><div class="pixel-attributes">'+C.axes(g).map(a=>'<div class="pixel-attribute"><b>'+a.name+' '+productKnowledge(a.id)+'</b><span class="attribute-pips" aria-label="'+g.attributes[a.id]+' de 5">'+Array.from({length:5},(_,i)=>'<i class="'+(i<g.attributes[a.id]?'filled':'')+'"></i>').join('')+'</span>'+button('−','attribute','data-id="'+a.id+'" data-delta="-1" aria-label="Diminuir '+a.name+'" '+(!g.attributes[a.id]?'disabled':''),'secondary')+button('+','attribute','data-id="'+a.id+'" data-delta="1" aria-label="Aumentar '+a.name+'" '+(C.G.total(g)>=C.pointBudget(g)||g.attributes[a.id]>=5?'disabled':''),'secondary')+'</div>').join('')+'</div><div class="creation-radar">'+radar()+'</div>')+'<div class="creation-cost">Materiais: <b>'+money(C.unitCost(g))+' / unidade</b><small>Protótipo · R$4.000</small></div><div class="tray-foot">'+button(g.traction?'CONCLUIR PROJETO →':'ESCOLHER VITRINE →','reveal',g.phase==='design'&&g.boardCampaign&&!g.designPieces?.length?'disabled title="Encaixe ao menos uma peça"':'')+''+'</div>';}

 function forecastMarkup(state=g,draft=null){if(state.unitAcquisition){const cm=C.contribution(state);return '<div class="acquisition-strip"><span>CAC POR UNIDADE<b>'+money(cm.cac)+'</b></span><span>PRODUTO + CAC<b>'+money(cm.cost+cm.cac)+'</b></span><span>CONTRIBUIÇÃO<b class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'/un.</b></span></div><small>CAC cobrado nas unidades vendidas pela campanha. Sem reserva fixa; recomendações orgânicas têm aquisição zero.</small>';}if(state.commercial){const cm=C.contribution(state),metrics=C.acquisitionMetrics(state),held=C.reserved(state),budget=draft?C.campaignBudget(draft):state.acquisitionCampaigns.at(-1)?.budget||150+Object.values(state.promo).reduce((n,v)=>n+v,0)*100;return '<div class="acquisition-strip"><span>CAC POR CLIENTE<b>'+money(cm.cac)+'</b></span><span>CUSTO + CAC<b>'+money(cm.cost+cm.cac)+'</b></span><span>CONTRIBUIÇÃO APÓS CAC<b class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'/un.</b></span></div><small class="acquisition-note">Reserva da campanha: '+money(budget)+'. Só os novos clientes pagos consomem CAC; o saldo não usado volta ao caixa no fechamento.'+(held?' Reservado agora: '+money(held)+'.':'')+(metrics.customers?' Aquisição já realizada: '+money(metrics.budget)+'.':'')+'</small>';} if(state.reach){const known=C.acquisitionMetrics(state),budget=draft?C.campaignBudget(draft):state.recampaign?.cost||150+Object.values(state.promo).reduce((n,v)=>n+v,0)*100,cost=state.sales&&state.stock?state.inventoryBook/state.stock:C.batchUnitCost(state),cm={amount:state.price*(1-(C.place(state)?.fee||0))-cost};return '<div class="acquisition-strip"><span>VERBA DA CAMPANHA<b>'+money(budget)+'</b></span><span>CAC PAGO · REALIZADO<b>'+(known.cac===null?'A descobrir':money(known.cac))+'</b></span><span>MC COM CAC HISTÓRICO<b>'+(known.cac===null?'Após as vendas':money(cm.amount-known.cac)+'/un.')+'</b></span></div><small class="acquisition-note">'+(known.cac===null?'Observe as vendas e os reviews para descobrir seu público.':'CAC usa só clientes das campanhas pagas. Recomendações têm origem separada.')+' Comissão e custo por unidade são conhecidos; vendas futuras ainda são uma aposta.</small>';}const f=C.forecast(state,draft);return '<div class="acquisition-strip"><span>AQUISIÇÃO<b>'+money(f.budget)+'</b></span><span>NOVOS CLIENTES · ESTIMATIVA<b>'+f.customers+'</b></span><span>CAC ESTIMADO<b>'+(f.cac===null?'-':money(f.cac))+'</b></span><span>MC APÓS CAC · ESTIMADA<b class="'+(f.after!==null&&f.after<0?'negative':'')+'">'+(f.after===null?'-':money(f.after)+' / un.')+'</b></span></div><small class="acquisition-note">CAC = gasto de aquisição ÷ novos clientes. Projeção de uma unidade por novo cliente, sujeita a preço, dado e estoque. Comissão não é CAC.'+(f.customers===0?' Nenhuma aquisição prevista neste cenário.':'')+'</small>';}
 function drawOverview(){const groups=C.overview(g);$('product-overview').hidden=!overviewOpen;if(!overviewOpen)return;
  const axes=C.axes(g),attrsOf=v=>v.id===g.id+'-'+g.cycle?g.attributes:(g.history.find(h=>h.account?.id===v.id||h.id===v.id)?.attributes||null);
  const kpi=(l,v,cls='')=>'<div class="vs-k '+cls+'"><small>'+l+'</small><b>'+v+'</b></div>';
  const cards=groups.map(r=>{const vs=r.versions,lastV=vs[vs.length-1]||{},kind=lastV.productId||vs[0]?.productId,neg=r.profit<0,avgPrice=r.sold?r.revenue/r.sold:(lastV.id===g.id+'-'+g.cycle?g.price:0),at=attrsOf(lastV),onShelf=(g.shelf||[]).find(p=>p.lineage===r.lineage&&!p.done),selling=onShelf||(r.lineage===(g.lineage||g.id+'-'+g.cycle)&&g.phase==='selling'),status=selling?'À venda':(r.stock>0?'Em estoque':'Esgotado');
   const stars=r.averageStars===null?'<small>sem avaliações</small>':'<span class="vs-stars">'+'★'.repeat(Math.round(r.averageStars))+'☆'.repeat(5-Math.round(r.averageStars))+'</span> <small>'+r.averageStars.toFixed(1).replace('.',',')+' ('+r.reviewCount+')</small>';
   const attrs=at?'<div class="vs-attrs">'+axes.filter(a=>(at[a.id]||0)>0).map(a=>'<span title="'+a.name+'"><i style="background:'+a.color+'"></i>'+a.name+'<b>'+(at[a.id]||0)+'</b></span>').join('')+'</div>':'';
   return '<article class="vs-card"><div class="vs-img">'+productIcon(kind,110)+'<span class="vs-lvl">NV '+(lastV.level||'?')+'</span><span class="vs-st '+(selling?'on':r.stock>0?'mid':'off')+'">'+status+'</span></div><div class="vs-body"><h3>'+esc(r.name)+'</h3><div>'+stars+'</div><div class="vs-price">'+(avgPrice?money(avgPrice):'-')+'</div>'+attrs+
    '<div class="vs-kpis">'+kpi('Vendidos',Number(r.sold||0).toLocaleString('pt-BR'))+kpi('Faturado',money(r.revenue||0))+kpi('Investido',money(r.invested||0))+kpi('Lucro',signedMoney(r.profit),neg?'neg':'pos')+kpi('ROI',r.invested?Math.round(r.profit/r.invested*100)+'%':'-',neg?'neg':'pos')+kpi('Estoque',Number(r.stock||0).toLocaleString('pt-BR'))+'</div>'+
    '<div class="vs-ver">'+vs.length+(vs.length>1?' versões':' versão')+': '+vs.map(v=>'NV'+v.level).join(' › ')+'</div></div></article>';}).join('');
  const newTile='<button class="vs-card vs-new" id="pv-new"><span>＋</span><b>DESENVOLVER NOVO PRODUTO</b><small>'+(g.phase==='selling'?'o atual continua vendendo na vitrine':'comece outra ideia do zero')+'</small></button>';
  $('product-overview').innerHTML='<div class="vs-shop"><div class="vs-top"><div><small>🛍️ LOJA VIRTUAL</small><h2>'+esc(g.company||'Sua empresa')+'</h2><span>'+groups.length+' produto'+(groups.length===1?'':'s')+' no catálogo</span></div>'+button('Voltar','closeOverview','','secondary')+'</div>'+(g.materialsCredit?'<p class="pv-credit">♻️ Materiais recuperados: <b>'+money(g.materialsCredit)+'</b> em crédito de produção</p>':'')+'<div class="vs-grid">'+cards+newTile+'</div></div>';
  const nb=$('pv-new');if(nb)nb.onclick=()=>{closeOverview();if(g.phase==='selling')dispatch({type:'launchNext'});else if(g.phase==='recap')dispatch({type:'next'});else{workshopCollapsed=false;dispatch({type:'workbench'});}};}
 function showOverview(){if(rolling){notify('Conclua a rolagem antes de abrir a prateleira.');return;}overviewWasPaused=g.paused;if(!g.paused)dispatch({type:'pause'});overviewOpen=true;drawOverview();}
 function closeOverview(){overviewOpen=false;drawOverview();if(!overviewWasPaused&&g.paused)dispatch({type:'pause'});}

 // rosto em pixel art: cabelo, pele, acessório e expressão variam por pessoa (mesmo nome = mesmo rosto)
 function pxFace(seed,shirt,hair,older){let h=0;for(const ch of String(seed||'x'))h=(h*31+ch.charCodeAt(0))>>>0;const pick=(n,k)=>Math.floor(h/k)%n;
  const SK=['#f6d2b4','#e8b48f','#c98b62','#9a6440','#6e4529'],sk=SK[pick(5,1)],hr=older?'#cfc8bd':(hair||'#3a2618'),sh=shirt||'#6b4fd8',ink='#241d33',dk='#00000040';
  const style=pick(6,7),acc=pick(5,43),smile=pick(3,211);const px={};const put=(x,y,c)=>{if(x>=0&&x<12&&y>=0&&y<12)px[x+','+y]=c;};const rect=(x0,y0,x1,y1,c)=>{for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++)put(x,y,c);};
  rect(1,10,10,11,sh);rect(5,9,6,9,sk);rect(3,3,8,8,sk);put(2,5,sk);put(9,5,sk);put(2,6,sk);put(9,6,sk);
  if(style===0){rect(3,1,8,2,hr);put(3,3,hr);put(8,3,hr);}
  else if(style===1){rect(3,1,8,2,hr);rect(2,2,2,8,hr);rect(9,2,9,8,hr);put(3,3,hr);put(8,3,hr);}
  else if(style===2){rect(3,1,8,2,hr);rect(5,0,6,0,hr);put(3,3,hr);put(8,3,hr);}
  else if(style===3){rect(2,0,9,2,hr);rect(1,1,1,5,hr);rect(10,1,10,5,hr);rect(2,3,2,4,hr);rect(9,3,9,4,hr);put(2,0,'');put(9,0,'');}
  else if(style===4){rect(3,1,8,2,hr);rect(3,3,5,3,hr);}
  else {rect(2,1,9,2,sh);rect(3,0,8,0,sh);rect(3,3,10,3,ink);}
  put(4,5,ink);put(7,5,ink);
  if(acc===0){rect(3,5,5,5,ink);rect(6,5,8,5,ink);put(4,5,'#cfe3ff');put(7,5,'#cfe3ff');}
  else if(acc===1&&!older){rect(3,7,8,8,hr);put(5,7,sk);put(6,7,sk);}
  else if(acc===2)put(2,7,'#f0c33c');
  else if(acc===3){put(3,6,'#e8908066');put(8,6,'#e8908066');}
  if(smile===0){put(5,7,'#9a3b3b');put(6,7,'#9a3b3b');}else if(smile===1){put(4,7,'#9a3b3b');put(5,8,'#9a3b3b');put(6,8,'#9a3b3b');put(7,7,'#9a3b3b');}else{put(5,7,'#9a3b3b');put(6,7,'#9a3b3b');put(6,8,dk);}
  if(older){put(3,4,'#00000022');put(8,4,'#00000022');}
  let r='';for(const k in px){if(!px[k])continue;const[x,y]=k.split(',');r+='<rect x="'+x+'" y="'+y+'" width="1" height="1" fill="'+px[k]+'"/>';}
  return '<svg viewBox="0 0 12 12" shape-rendering="crispEdges">'+r+'</svg>';}
 function personaCard(){return personaCard0()+saidHtml();}
 function personaCard0(){const p=C.client(g.phase==='recampaignPlan'&&g.campaignDraft?.clientId?{...g,clientId:g.campaignDraft.clientId}:g);if(!p)return '';return '<aside class="persona-reminder">'+mini(p)+'<div><b>'+esc(p.name)+' <small>'+esc(p.ageLabel)+' anos</small></b><p>'+esc(p.quote)+'</p>'+(p.comments||[]).map((t,i)=>'<p class="persona-comment pc'+(i+1)+'"><b class="pc-n">'+(i+1)+'</b><span class="pc-t">“'+boldKey(t,p.keys?.[i])+'”</span></p>').join('')+'</div></aside>';}
 function commercialPricing(){const cm=C.contribution(g);chooseGuide('ETIQUETA','Quanto vai custar?','');return pricingTagHtml()+'<div class="tray-foot">'+(g.priorPrice&&!g.pricingContext?button('Manter '+money(g.priorPrice),'keepPrice','','secondary'):'')+button(g.pricingContext==='recampaign'?'Voltar à campanha →':'Preparar lançamento →','confirmPrice')+'</div>';return '<div class="pricing-desk">'+gadgetArt()+'<div class="grow"><div class="price-calculation"><span>PRODUTO<b>'+money(cm.cost)+'</b></span>'+(g.traction?'':'<span>CAC<b>'+money(cm.cac)+'</b></span><span>POR VENDA<b>'+money(cm.cost+cm.cac)+'</b></span>')+'</div><label>Preço de venda <input id="sale-price" type="number" min="0.01" step="0.01" value="'+g.price.toFixed(2)+'" aria-label="Preço em reais"></label><h2 id="calculated-price">'+money(g.price)+'</h2><label for="margin">Margem de contribuição <b id="margin-value">'+cm.percent.toFixed(1)+'%</b></label><input id="margin" type="range" min="-100" max="80" step="1" value="'+Math.max(-100,Math.min(80,cm.percent))+'"><div class="price-tags">'+[15,35,45].map(m=>button(m+'%','margin','data-margin="'+m+'"',Math.abs(g.margin-m)<.1?'selected':'secondary')).join('')+'</div><p class="unit-return">Por venda <b id="gross-value" class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'</b></p><div id="pricing-acquisition" hidden></div></div></div><div class="tray-foot">'+(g.priorPrice&&!g.pricingContext?button('Manter '+money(g.priorPrice),'keepPrice','','secondary'):'')+button(g.pricingContext==='recampaign'?'Voltar à campanha →':'Preparar lançamento →','confirmPrice')+'</div>';}
 function stockHud(){const producing=g.crew?.type==='produce'?g.crew.quantity:0,left=Math.max(0,(g.sales?.windowEnd||g.clock)-g.clock)/60,low=g.stock<Math.max(20,g.produced*.15);return '<div class="stock-hud '+(low?'stock-low':'')+'"><span>📦 PRONTOS <b id="stock-live">'+g.stock+'</b></span><span>⚒ EM PRODUÇÃO <b id="making-live">'+producing+'</b></span>'+(g.personaSet==='v2'?'</div>':'<span>⌛ RESTAM <b id="life-left">'+left.toFixed(1)+' dias</b></span></div><div class="progress life-progress"><i id="life-progress" style="width:'+Math.max(0,Math.min(100,left/7*100))+'%"></i></div>')+'<p class="stock-hint">'+(low?'📦 Está acabando.':'')+'</p>';}
 function personaKnowledge(id){const n=Object.values(g.learning?.facts||{}).filter(f=>['product','minimum'].includes(f.kind)&&f.productId===g.productId&&f.personaId===id).length;return n?'<small class="persona-memory">📘 '+n+' descoberta(s) guardada(s)</small>':'';}
 function productKnowledge(axis){const a=C.Learning.productHint(g,axis),m=C.Learning.minimumHint(g,axis);return '<span class="knowledge-badge '+(a?'confirmed':'unknown')+'" title="'+esc(a?a.text:'Ainda não investigado para este produto e persona')+'">'+esc(a?.symbol||'?')+'</span>'+(m?'<span class="knowledge-badge need" title="'+esc(m.text)+'">!</span>':'');}
 function campaignKnowledge(channel){const hints=C.Learning.channelHints(g,channel);return '<small class="channel-knowledge">'+(hints.length?hints.map(f=>esc(C.Reach.ages[f.age])+' <b class="knowledge-badge confirmed">'+esc(f.symbol)+'</b>').join(' · '):'Afinidades a descobrir · ?')+'</small>';}
 function learningPrompt(){if(!g.unitAcquisition)return '';const r=C.Learning.record(g),ready=['product','campaign'].some(d=>C.Learning.status(g,d).ready);return '<aside class="learning-invite"><span class="learning-lamp">💡</span><div><b>'+ (r?(r.cards.length?'Uma descoberta para a próxima decisão.':'A experiência ficou guardada.'):'O que essa experiência pode ensinar?')+'</b><small>'+(r?'A tentativa desta campanha já foi registrada.':ready?'Conhecimento fica na empresa e reaparece nas próximas criações.':'Precisamos de mais evidências ou de um experimento diferente.')+'</small></div>'+(g.prog?button('📘 Deduzir no livro','bookOpen','','secondary'):button(r?'Rever investigação':'Tirar uma lição 🎲','learningOpen',!r&&!ready?'disabled':'','secondary'))+'</aside>';}
 function learningPanel(){const k=g.learning,record=C.Learning.record(g),domain=k.domain||'product',leader=C.Learning.leader(g,domain),mods=C.Learning.modifiers(g,domain),bonus=mods.reduce((n,m)=>n+m.value,0),hidden=!!rolling,m=C.windowMetrics(g);chooseGuide('DEPOIS DO EXPEDIENTE','Vamos ligar os pontos.','');const facts='<p class="learning-facts">'+m.seen+' contatos · '+m.sold+' unidades vendidas · operação '+money(m.operatingProfit)+'</p>';if(record)return facts+'<div class="learning-scene">'+dieHTML(record.roll,null)+'<div class="learning-copy">'+(hidden?'<h2>Ligando os pontos…</h2><p>A equipe procura uma conclusão.</p>':'<h2>'+(record.cards.length?'💡 Descoberta registrada!':'Ainda falta ligar os pontos.')+'</h2>'+formula(record.roll)+'<p>Alvo 11 · '+esc(record.analyst)+'</p>'+(record.cards.length?'<div class="knowledge-rewards">'+record.cards.map(f=>'<article class="knowledge-card"><strong>'+esc(f.symbol)+'</strong><h3>'+esc(f.title)+'</h3><p>'+esc(f.text)+'</p><small>Guardado na memória da empresa</small></article>').join('')+'</div>':'<p>Seus feedbacks e resultados continuam disponíveis. A intuição acumulada ajudará na próxima experiência deste assunto.</p>'))+'</div></div><div class="tray-foot">'+(hidden?'':button('Voltar ao quarto','learningClose'))+'</div>';
 return facts+'<div class="learning-domains">'+[{id:'product',name:'Produto',icon:'🎧',question:'O que importa para essa persona?'},{id:'campaign',name:'Campanha',icon:'📣',question:'Quem descobre novidades por aqui?'}].map(d=>{const status=C.Learning.status(g,d.id);return button('<span>'+d.icon+'</span><b>'+d.name+'</b><small>'+d.question+'</small><small>'+esc(status.reason)+'</small>','learningDomain','data-domain="'+d.id+'" '+(!status.ready?'disabled':''),domain===d.id?'selected':'secondary');}).join('')+'</div><div class="learning-scene">'+dieHTML(null,'learningRoll')+'<div class="learning-copy"><h2>D20 + '+bonus+' · alvo 7</h2><p>'+esc(leader.name)+' · análise +'+leader.skill+(k.intuition[domain]?' · intuição +'+k.intuition[domain]:'')+'</p><p>'+Math.min(80,50+bonus*5)+'% de chance · uma tentativa nesta campanha</p>'+(C.Learning.analysts(g).length>1?'<div class="price-tags">'+C.Learning.analysts(g).map(p=>button(esc(p.name)+' · +'+(p.skills[domain]||0),'learningAnalyst','data-id="'+esc(p.id)+'"',p.id===leader.id?'selected':'secondary')).join('')+'</div>':'')+button('Investigar com D20 🎲','learningRoll')+'</div></div><div class="tray-foot">'+button('Voltar sem investigar','learningClose','','secondary')+'</div>';}
