 function portrait(p,size=64){const h=[...String(p?.name||'?')].reduce((n,ch)=>n+ch.charCodeAt(0),0),hair=['#2b2b2b','#5a3b26','#d9a441','#a33b2b','#3b2a2a'][h%5],skin=['#edbd97','#d79a72','#b9805a','#f1c9a5'][h%4],shirt=p?.founder?'#f2a93b':(AREA_STYLE[p?.area]?.[0]||'#7b5cd6');return '<svg class="pt" width="'+size+'" height="'+size+'" viewBox="0 0 16 16" shape-rendering="crispEdges" aria-hidden="true"><rect width="16" height="16" fill="#e9e1cc"/><rect x="3" y="11" width="10" height="5" fill="'+shirt+'"/><rect x="6" y="10" width="4" height="2" fill="'+skin+'"/><rect x="4" y="3" width="8" height="7" fill="'+skin+'"/><rect x="4" y="2" width="8" height="2" fill="'+hair+'"/><rect x="3" y="3" width="1" height="4" fill="'+hair+'"/><rect x="12" y="3" width="1" height="4" fill="'+hair+'"/><rect x="6" y="6" width="1" height="1" fill="#1d1b26"/><rect x="9" y="6" width="1" height="1" fill="#1d1b26"/><rect x="7" y="8" width="2" height="1" fill="#b5677c"/></svg>';}
 function weeklyDrift(d){const st=g.team?.staff||[],lift=p=>(p.trait==='ESFP'?3:0)+(p.trait==='ENTJ'&&C.moodBand(p)==='inspired'?3:0)+Math.floor(p.level/4);let x=-8+.4*(d.level-1)-(d.trait==='ISTP'?2:0);if(d.trait==='ISTJ')x*=.5;if(d.trait==='ENFP')x*=2;if(d.trait==='ESTP'&&x<0)x*=2;return x+st.filter(p=>p!==d).reduce((n,p)=>n+lift(p),0);}
 const fmtN=v=>(v>0?'+':v<0?'−':'')+String(Math.abs(Math.round(v*10)/10)).replace('.',',');
