 function weeklyPopup(){
  const node=$('weekly-modal'),w=g.weekly,wasHidden=node.hidden;
  node.hidden=!w||(w.stage==='work'&&!weeklyHistoryOpen);
  if(node.hidden)return;
  const r=w.reports.at(-1);
  if(r&&w.stage!=='work'&&!weeklyHistoryOpen&&Sfx.onceFor('week'+r.number)){Sfx.play('brk');setTimeout(()=>Sfx.play('week'),700);}
  let html;
  if(weeklyHistoryOpen){
   html='<h2>Histórico semanal</h2>'+weeklyHistory()+w.insights.map(i=>'<p><b>'+esc(i.product)+'</b> · '+esc(i.insight)+'</p>').join('')+
    button('Voltar','weeklyHistoryClose','','secondary');
  }else{
   // Panorama da semana: destaques primeiro, contas detalhadas recolhidas, e a escolha do fim de semana no fim
   const previous=w.reports.at(-2);
   const difference=key=>{
    if(!previous)return '<small>Primeira semana</small>';
    const delta=r[key]-previous[key];
    const signed=(delta>0?'+':'')+money(delta);
    const percent=previous[key]===0?'sem base comparável':new Intl.NumberFormat('pt-BR',{style:'percent',signDisplay:'exceptZero',maximumFractionDigits:1}).format(delta/Math.abs(previous[key]));
    return '<small>'+signed+' · '+percent+'</small>';
   };
   const tile=(label,key)=>'<div>'+label+' '+(key==='costs'?cost(r[key]):signedMoney(r[key]))+difference(key)+'</div>';
   const reconciliation=r.cashDifference??Math.round((r.cashEnd-r.cashStart-r.inflow+r.outflow)*100)/100;
   const contas=
    '<div class="week-totals">'+tile('Receita','revenue')+tile('Despesas','costs')+tile('Resultado','result')+'</div>'+weekChart(w.reports,r.number)+
    (previous?'<p class="week-comparison">Em relação à semana '+previous.number+'</p>':'')+
    (r.cashEnd<0?'<p class="week-alert" role="alert">Caixa negativo · '+money(r.cashEnd)+'</p>':'')+
    (reconciliation?'<p class="week-alert" role="alert">Diferença na conciliação · '+money(reconciliation)+'</p>':'')+
    '<div class="week-finance"><section><h3>Despesas por categoria</h3>'+
    (Object.entries(r.expenses).filter(([,n])=>n).map(([k,n])=>'<div>'+esc(C.moneyCategories[k]||'Custos fixos')+' '+cost(n)+'</div>').join('')||'<p>Sem despesas nesta semana.</p>')+
    '</section><section><h3>Caixa</h3><div>Saldo inicial <b>'+money(r.cashStart)+'</b></div><div>Recebimentos <b>'+money(r.inflow)+'</b></div><div>Pagamentos '+cost(r.outflow)+'</div>'+
    '<div class="week-cash-end">Saldo final '+signedMoney(r.cashEnd)+'</div></section></div>'+
'';
   const up=(now,before)=>{if(before==null||!Number.isFinite(before)||before===0)return '';const d=(now-before)/Math.abs(before);return ' <em class="'+(d>=0?'up':'down')+'">'+(d>=0?'▲':'▼')+' '+new Intl.NumberFormat('pt-BR',{style:'percent',maximumFractionDigits:0}).format(Math.abs(d))+'</em>';};
   const byDay={};for(const e of r.entries||[])if(e.category==='receita')byDay[e.day%5]=(byDay[e.day%5]||0)+e.amount;
   const best=Object.entries(byDay).sort((x,y)=>y[1]-x[1])[0],ws=w.weekendSales&&w.weekendSales.week===r.number-1&&w.weekendSales.units?w.weekendSales:null,rev=(g.reviews||[]).at(-1);
   const hl=[['💰','Resultado',signedMoney(r.result)+up(r.result,previous?.result)],['🧾','Receita',money(r.revenue)+up(r.revenue,previous?.revenue)],['👥','Clientes novos',String(r.customers||0)+up(r.customers||0,previous?.customers)],
    best?['📅','Melhor dia',['Segunda','Terça','Quarta','Quinta','Sexta'][+best[0]]+' · '+money(best[1])]:null,
    r.audience>0?['📣','Público',Math.round(r.audience).toLocaleString('pt-BR')+' pessoas · reputação '+Math.round(r.reputation||0)]:null,
    ws?['🌳','Fim de semana passado','A loja vendeu '+ws.units+' · '+money(ws.revenue)]:null,
    (g.prog?['📈','Bolsa de componentes',bolsaWeek()]:null),(g.prog&&g.productId&&C.Prog.RIVALS[g.productId]?['🏆','Ranking · '+catName(g.productId),rankLine()]:null),rev?['⭐','Última avaliação','<span class="wk-stars">'+'★'.repeat(rev.stars)+'☆'.repeat(5-rev.stars)+'</span> “'+esc(String(rev.feedback||'').slice(0,80))+'”']:null].filter(Boolean);
   const passeio=g.life?.outing?.week===w.reports.length;
   html='<small>FIM DA SEMANA '+String(r.number).padStart(2,'0')+'</small><h2>Panorama da semana</h2>'+
    '<div class="wk-hl">'+hl.map(([ic,l,v])=>'<div><span>'+ic+'</span><small>'+l+'</small><b>'+v+'</b></div>').join('')+'</div>'+
    (r.cashEnd<0?'<p class="week-alert" role="alert">Caixa negativo · '+money(r.cashEnd)+'</p>':'')+
    (r.events.length?'<div class="wk-marcos"><h3>Marcos da semana</h3><ul>'+r.events.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul></div>':'')+
    '<details class="wk-contas"><summary>Ver as contas da semana</summary>'+contas+(r.events.length?'':'')+'</details>'+
    '<h3 class="wk-q">E o fim de semana?</h3><div class="weekend-choices wk-two">'+
    (passeio?button('<b>🌳 Continuar o passeio</b>','weekPick','data-choice="town"'):
     button('<b>💼 Trabalhar</b>','weekPick','data-choice="work"')+
     button('<b>'+(g.office?'🌳':'🔒')+' Passar o fim de semana</b>','weekPick','data-choice="town"','secondary'+(g.office?'':' locked')))+
    '</div><div class="tray-foot">'+button('Histórico','weeklyHistory','','secondary')+'</div>';
  }
  node.innerHTML='<article class="week-sheet">'+html+'</article>';
  if(wasHidden||!node.contains?.(document.activeElement))node.querySelector?.('button:not([disabled])')?.focus?.();
 }
