  if(t==='rivalAxis'){const id=rivalPickId;try{const next=C.act(g,{type:'deduceRival',rival:id,axis:action.id});persist(next);g=next;notify(g.prog.rivals.k[id].weak?'✓ Acertou! O ponto fraco foi para o livro.':'✗ Não é esse. O atributo ficou riscado.');}catch(e){notify(e.message);}rivalPickId=null;knowledgeBook();render();return;}
