  const seq=g.team?.lastTraining?.seq;dispatch0(action);
  if(g.prog&&g.phase==='blueprint'&&action.type!=='build'&&autoBuild!==g.id+':'+g.cycle){autoBuild=g.id+':'+g.cycle;dispatch0({type:'build'});}
