 function funnelData(m){const seen=Math.max(g.leads||0,m.conversionContacts||0),ent=m.conversionContacts||0,buy=m.buyers||0,R=g.sales?.reasons||{},top=Object.entries(R).filter(([k])=>WHY[k]).sort((a,b)=>b[1]-a[1])[0];return{seen,ent,buy,why:top&&top[1]>0?'Quem entrou e não comprou: <b>'+WHY[top[0]]+'</b> ('+top[1].toLocaleString('pt-BR')+')':'Ainda sem desistências.'};}
