 // durante as vendas: só os botões que fazem sentido agora
 function sellActs(){const force=g.boardCampaign?Math.max(.2,.75**(g.sales?.fadeWave||0)):1,low=g.stock<=Math.max(10,Math.round((g.batchSize||100)*.2)),L=[];
  if(low)L.push(lsAct('📦','Repor','stockPlanToggle',!!g.crew));if(force<=.4)L.push(lsAct('📣','Campanha','campaignNow'));L.push(lsAct('🏷','Preço','priceEdit'));if(C.teamMember(g,'finance'))L.push(lsAct('⏱','Programar','storeAuto'));L.push(lsAct('⏹','Encerrar','stopSales'));return L.join('');}
